"""Working demo for this book record: full reader + HTML exporter.
Run:  python3 book_demo.py              (prints the whole book)
      python3 book_demo.py 3            (prints chapter 3 only)
      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'Aladdin and the Wonderful Lamp', 'author': 'Traditional (Arabian Nights)', 'genre': 'Tales of the Arabian Nights', 'chapters': [{'n': 1, 'title': 'Complete Text', 'text': "There once lived in China a poor tailor with his wife and son Aladdin, a careless, idle boy. When his father died, Aladdin idled in the streets. One day a stranger, a magician from Africa, claimed to be his uncle and hired him. He led Aladdin to a lonely place, lit a fire, and threw powder on it, and the earth opened, showing steps down to treasure. 'Go down,' said the magician, 'and bring me the old lamp you will find. Touch nothing else.' Aladdin descended, saw gardens of jewel fruits, and found the lamp. But when he tried to climb out, the magician demanded the lamp first, and Aladdin refused until he was out. In anger the magician sealed the earth, leaving Aladdin trapped. Weeping, Aladdin wrung his hands, and rubbed a ring the magician had lent him. A genie appeared: 'I am the slave of the ring. What is your wish?' Aladdin wished to be home, and was instantly transported. His mother cleaned the lamp, and rubbing it, summoned a mightier genie, slave of the lamp, who could grant any wish. With the genie's help, Aladdin grew rich, built a splendid palace, and won the Sultan's daughter, the Princess Badroulbadour, for his wife. The magician, learning of this, returned in disguise as a lamp-seller crying 'New lamps for old!' The princess, not knowing the lamp's value, traded it. The magician commanded the genie to carry the palace and princess to Africa. Aladdin, in despair, rubbed the ring, and its genie carried him to Africa. There Aladdin had the princess drug the magician's wine; while he slept, Aladdin seized the lamp, and commanded its genie to return the palace to China. The magician was executed, and Aladdin and his princess lived happily, and at the Sultan's death Aladdin succeeded to the throne."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

